1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { lstatSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import { randomUUID } from 'node:crypto';
6	import {
7	  FIELD_LIMITS,
8	  checkIdeaContent,
9	  isCompleteIdea,
10	  normalizeIdea,
11	  fieldRulesBrowserScript,
12	  type ContentErrorCode,
13	} from './idea-fields.ts';
14	
15	const PRODUCT: string = 'FeatureHarbor';
16	const RESOURCE: string = 'ideas';
17	const MAX_BODY_BYTES = 1_000_000;
18	// 严格 UTF-8 解码器：fatal 模式遇到非法字节直接抛错，而不是像 Buffer.toString('utf8')
19	// 那样把坏字节静默替换成“�”。请求正文与磁盘上的已有意见都先在完整的字节缓冲上通过它，
20	// 才允许进入 JSON 解析；分段送达在缓冲拼接后判断，合法多字节字符被拆到相邻段不算损坏。
21	const UTF8_DECODER = new TextDecoder('utf-8', { fatal: true });
22	// 接口侧把共用的内容判定结果映射成原有的错误说明；首页另有自己的措辞。
23	const CONTENT_ERROR_MESSAGES: Record<ContentErrorCode, string> = {
24	  'title-empty': '标题去掉首尾空白后不能为空',
25	  'title-too-long': `标题最多 ${FIELD_LIMITS.title} 个字符`,
26	  'description-empty': '详细说明必须包含非空白内容',
27	  'description-too-long': `详细说明最多 ${FIELD_LIMITS.description} 个字符`,
28	  'scenario-too-long': `使用场景最多 ${FIELD_LIMITS.scenario} 个字符`,
29	};
30	const PAGE: string = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FeatureHarbor · 产品意见与公开路线图</title><style>
31	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
32	a{color:#175b9c}
33	label{display:block;font-weight:600;margin-top:1rem}
34	input,textarea{width:100%;box-sizing:border-box;padding:.4rem;font:inherit}
35	textarea{resize:vertical}
36	.required{color:#b00020}
37	button{margin-top:1rem;padding:.5rem 1.2rem;font:inherit}
38	#error{color:#b00020;margin-top:.75rem}
39	#success{color:#1a7f37;margin-top:.75rem}
40	.idea{border-top:1px solid #ddd;padding:1rem 0}
41	.idea h3{margin:0 0 .5rem}
42	.view-link{display:inline-block;margin-top:.5rem}
43	.pre{white-space:pre-wrap}
44	time{color:#666;font-size:.9rem}
45	#search-form{margin:1rem 0}
46	#search-form input{max-width:20rem;margin-right:.5rem}
47	#search-form button{margin-top:.25rem;margin-right:.5rem}
48	</style><main><h1>FeatureHarbor</h1><p>产品意见与公开路线图</p>
49	<h2>提交产品意见</h2>
50	<form id="idea-form" novalidate>
51	<label for="f-title">标题 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.title} 字）</label>
52	<input id="f-title" name="title" required>
53	<label for="f-desc">详细说明 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.description} 字）</label>
54	<textarea id="f-desc" name="description" rows="5" required></textarea>
55	<label for="f-scenario">使用场景（可选，最多 ${FIELD_LIMITS.scenario} 字）</label>
56	<textarea id="f-scenario" name="scenario" rows="3"></textarea>
57	<button type="submit">提交意见</button>
58	<p id="error" role="alert" hidden></p>
59	<p id="success" role="status" hidden></p>
60	</form>
61	<h2>意见列表</h2>
62	<form id="search-form" role="search" novalidate>
63	<label for="f-search">关键词搜索</label>
64	<input id="f-search" name="q" type="search" placeholder="搜索标题、详细说明或使用场景" autocomplete="off">
65	<button type="submit">搜索</button>
66	<button id="search-clear" type="button">清空</button>
67	</form>
68	<p id="empty" hidden>还没有意见记录。</p>
69	<div id="ideas"></div>
70	<p><a href="/api/ideas">查看意见列表接口</a> · <a href="/health">服务状态</a></p>
71	</main><script>
72	${fieldRulesBrowserScript}
73	const form = document.getElementById('idea-form');
74	const titleInput = document.getElementById('f-title');
75	const descInput = document.getElementById('f-desc');
76	const scenarioInput = document.getElementById('f-scenario');
77	const errorBox = document.getElementById('error');
78	const successBox = document.getElementById('success');
79	const emptyNote = document.getElementById('empty');
80	const list = document.getElementById('ideas');
81	const searchForm = document.getElementById('search-form');
82	const searchInput = document.getElementById('f-search');
83	const searchClear = document.getElementById('search-clear');
84	const EMPTY_TEXT = '还没有意见记录。';
85	const NOT_FOUND_TEXT = '没有找到符合关键词的意见。';
86	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
87	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
88	let listState = 'loading';
89	// 已生效的搜索关键词：去掉首尾空白后的完整一段文字，空字符串表示不搜索。
90	// 只影响当前页面的可见结果，不发起请求、不改变已保存记录与接口返回。
91	let activeKeyword = '';
92	// 纯文字的大小写不敏感包含判断：关键词内部空格按原文参与比较，
93	// 不拆词；标点、尖括号与看起来像正则表达式的文字都按普通文字查找，
94	// 因此直接用 includes，不能走正则。
95	function ideaMatches(idea, keyword) {
96	  const needle = keyword.toLowerCase();
97	  return idea.title.toLowerCase().includes(needle)
98	    || idea.description.toLowerCase().includes(needle)
99	    || idea.scenario.toLowerCase().includes(needle);
100	}
101	function showError(message) {
102	  errorBox.textContent = message;
103	  errorBox.hidden = false;
104	  successBox.hidden = true;
105	}
106	function renderIdea(idea) {
107	  const item = document.createElement('article');
108	  item.className = 'idea';
109	  const heading = document.createElement('h3');
110	  heading.textContent = idea.title;
111	  const desc = document.createElement('p');
112	  desc.className = 'pre';
113	  desc.textContent = idea.description;
114	  item.append(heading, desc);
115	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
116	    const scenario = document.createElement('p');
117	    const label = document.createElement('strong');
118	    label.textContent = '使用场景：';
119	    const text = document.createElement('span');
120	    text.className = 'pre';
121	    text.textContent = idea.scenario;
122	    scenario.append(label, text);
123	    item.append(scenario);
124	  }
125	  const time = document.createElement('time');
126	  time.dateTime = idea.createdAt;
127	  const parsed = new Date(idea.createdAt);
128	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
129	  item.append(time);
130	  // 每条已保存意见都有独立查看入口（搜索过滤后的结果与本页新提交同样带入口）：
131	  // 链接只由该记录的标识 id 决定，与标题、说明文字无关；id 经 encodeURIComponent
132	  // 编码，历史标识里的中文、空格或网址特殊字符也能准确指向自己的记录。
133	  // 历史标题可能为空，但入口不依赖标题，空标题记录仍可打开。
134	  const viewLink = document.createElement('a');
135	  viewLink.className = 'view-link';
136	  viewLink.href = '/ideas/' + encodeURIComponent(idea.id);
137	  viewLink.textContent = '查看这条意见';
138	  item.append(viewLink);
139	  return item;
140	}
141	let remoteIdeas = [];
142	// 本页已确认保存的意见，按本页发起提交的先后排列：后提交的在前。
143	// 每条记录带上点击提交时的序号，响应返回的先后不影响排列位置
144	const submittedIdeas = [];
145	function renderList() {
146	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
147	  const seen = new Set();
148	  const ordered = [];
149	  for (const entry of submittedIdeas) {
150	    const idea = entry.idea;
151	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
152	  }
153	  for (const idea of remoteIdeas) {
154	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
155	  }
156	  // 搜索只过滤当前页面的可见结果：沿用合并后的原有顺序，逐条判断、不去重不重排，
157	  // 同一条意见最多出现一次；匹配的意见仍按原文渲染（保留空白与换行），不删改内容。
158	  const visible = activeKeyword
159	    ? ordered.filter((idea) => ideaMatches(idea, activeKeyword))
160	    : ordered;
161	  list.replaceChildren(...visible.map(renderIdea));
162	  if (listState === 'failed') {
163	    // 加载失败优先显示现有的失败提示，不能把失败显示成搜索无结果
164	    emptyNote.textContent = LOAD_FAILED_TEXT;
165	    emptyNote.hidden = false;
166	  } else if (listState !== 'ready') {
167	    // 首次列表仍在加载，不能把等待误报成没有记录或没有匹配结果
168	    emptyNote.hidden = true;
169	  } else if (activeKeyword) {
170	    // 搜索已生效：完整列表是否为空决定提示措辞，已有意见但无匹配时明确提示未找到
171	    emptyNote.textContent = ordered.length === 0 ? EMPTY_TEXT : NOT_FOUND_TEXT;
172	    emptyNote.hidden = visible.length > 0;
173	  } else {
174	    emptyNote.textContent = EMPTY_TEXT;
175	    emptyNote.hidden = ordered.length > 0;
176	  }
177	}
178	// 一条意见记录是否完整，直接使用 idea-fields.ts 注入的同一份 isCompleteIdea：
179	// 与服务读取已有数据的判定逐字相同，列表加载与提交确认都调用它，不在页面另写第二份。
180	async function loadIdeas() {
181	  try {
182	    const res = await fetch('/api/ideas');
183	    if (!res.ok) throw new Error('load failed');
184	    const data = await res.json();
185	    // 列表响应必须是带 ideas 数组的 JSON 对象，且数组中每条记录都完整；
186	    // 顶层结构异常或任意一条记录不完整都属于整次加载失败，
187	    // 即使异常记录前面有正常意见，也不能只展示其中一部分
188	    if (typeof data !== 'object' || data === null || Array.isArray(data) || !Array.isArray(data.ideas)) {
189	      throw new Error('invalid ideas response');
190	    }
191	    if (!data.ideas.every(isCompleteIdea)) throw new Error('invalid idea record');
192	    remoteIdeas = data.ideas;
193	    listState = 'ready';
194	  } catch {
195	    listState = 'failed';
196	  }
197	  renderList();
198	}
199	// 任一字段每次发生编辑都递增；提交时记下当前版本，成功响应到达时若版本未变，
200	// 说明等待期间没有继续编辑，才清空表单，否则保留正在写的草稿
201	let editVersion = 0;
202	for (const field of [titleInput, descInput, scenarioInput]) {
203	  field.addEventListener('input', () => { editVersion += 1; });
204	}
205	// 字段内容判定与接口共用同一份实现（FIELD_LIMITS、codePointCount、checkIdeaContent
206	// 由 idea-fields.ts 注入）；这里只把共用判定结果映射成本页原有的提示措辞与顺序。
207	function validate(title, description, scenario) {
208	  switch (checkIdeaContent(title, description, scenario)) {
209	    case 'title-empty': return '标题不能为空。';
210	    case 'title-too-long': return '标题最多 ' + FIELD_LIMITS.title + ' 个字符。';
211	    case 'description-empty': return '详细说明不能为空。';
212	    case 'description-too-long': return '详细说明最多 ' + FIELD_LIMITS.description + ' 个字符。';
213	    case 'scenario-too-long': return '使用场景最多 ' + FIELD_LIMITS.scenario + ' 个字符。';
214	    default: return null;
215	  }
216	}
217	// 每次点击提交都递增：成功或失败提示只属于最近一次点击。
218	// 更早发出的请求即使更晚返回，也只能在服务确认保存时更新列表，不能改动当前提示。
219	let latestSubmitSeq = 0;
220	form.addEventListener('submit', async (event) => {
221	  event.preventDefault();
222	  const submitSeq = ++latestSubmitSeq;
223	  // 用户发起新的提交后，上一条操作的提示先清除；在本次点击有结果前，
224	  // 更早请求迟到返回也不能重新显示成功或失败，也不能让人误以为正在提交的意见已保存
225	  errorBox.hidden = true;
226	  successBox.hidden = true;
227	  const title = titleInput.value;
228	  const description = descInput.value;
229	  const scenario = scenarioInput.value;
230	  const submittedVersion = editVersion;
231	  const problem = validate(title, description, scenario);
232	  // 被表单直接拦下的一次点击同样是用户最近的提交操作，字段错误即本次点击的结果；
233	  // 之后更早请求的返回不能掩盖它
234	  if (problem) { showError(problem); return; }
235	  let res;
236	  try {
237	    res = await fetch('/api/ideas', {
238	      method: 'POST',
239	      headers: { 'content-type': 'application/json' },
240	      body: JSON.stringify({ title, description, scenario })
241	    });
242	  } catch {
243	    if (submitSeq === latestSubmitSeq) showError('网络错误，提交未成功，请重试。');
244	    return;
245	  }
246	  let data = null;
247	  try { data = await res.json(); } catch { data = null; }
248	  if (!res.ok) {
249	    if (submitSeq === latestSubmitSeq) {
250	      showError(data && data.error ? '提交失败：' + data.error : '提交失败，请稍后重试。');
251	    }
252	    return;
253	  }
254	  // 成功状态的响应同样必须记录完整：顶层是含 idea 的 JSON 对象，
255	  // 且 idea 本身通过 isCompleteIdea 校验（对象、非空 id、各字段均为字符串）。
256	  // 空对象、数组或缺字段的记录不能当作保存成功：不显示成功提示、
257	  // 不清空草稿、不并入列表，也不用表单内容补齐响应缺失的信息
258	  const saved = typeof data === 'object' && data !== null && !Array.isArray(data) && isCompleteIdea(data.idea);
259	  if (!saved) {
260	    if (submitSeq === latestSubmitSeq) showError('提交失败，请稍后重试。');
261	    return;
262	  }
263	  const idea = data.idea;
264	  // 是否清空表单只取决于等待期间有没有继续编辑（包括改回原文、清空字段也算编辑），
265	  // 与响应返回先后无关：过期请求确认保存时也不能清掉用户正在写的草稿
266	  if (editVersion === submittedVersion) form.reset();
267	  // 只要服务确认保存，意见就进入列表，即使这条请求已不是最近一次点击：
268	  // 不能为了避免提示干扰而丢弃真实保存结果。
269	  // 位置按本页发起提交的先后确定（后提交的在前），与响应返回先后无关：
270	  // 先提交的意见迟到确认时补到后提交的意见之后，不能把它挤到更靠后的位置
271	  const entry = { seq: submitSeq, idea };
272	  let insertAt = submittedIdeas.findIndex((e) => e.seq < submitSeq);
273	  if (insertAt === -1) insertAt = submittedIdeas.length;
274	  submittedIdeas.splice(insertAt, 0, entry);
275	  renderList();
276	  // 成功提示只属于最近一次点击：更早的请求迟到返回时，不能在最新一次的失败提示
277	  // 或新一次提交的等待旁边再显示成功
278	  if (submitSeq === latestSubmitSeq) {
279	    successBox.textContent = '提交成功，你的意见已保存。';
280	    successBox.hidden = false;
281	  }
282	});
283	// 搜索只在本页过滤已合并的完整列表：提交搜索表单不发起任何请求、不提交意见，
284	// 也不清空或改写提交意见表单里的草稿；关键词去掉首尾空白后为空时恢复完整列表。
285	// 已生效后，迟到的首次列表与本页新确认保存的意见都会在 renderList 中继续按它过滤。
286	function applySearch() {
287	  activeKeyword = searchInput.value.trim();
288	  renderList();
289	}
290	searchForm.addEventListener('submit', (event) => {
291	  event.preventDefault();
292	  applySearch();
293	});
294	searchClear.addEventListener('click', () => {
295	  searchInput.value = '';
296	  activeKeyword = '';
297	  renderList();
298	});
299	loadIdeas();
300	</script></html>`;
301	const VIEW_PATH_PREFIX = '/ideas/';
302	// 单条意见查看页只展示常规字段（标题、完整详细说明、非空白使用场景、提交时间），
303	// 记录携带的附加信息一律不在页面公开。与首页一样，历史内容不重新套用新提交的限制：
304	// 超限、空白标题/说明、换行、中文、表情、网页标记样文本与实体写法都按原文显示。
305	const VIEW_FIELD_LABELS = {
306	  scenario: '使用场景',
307	  createdAt: '提交时间',
308	} as const;
309	// 服务端渲染时把所有意见文字按普通文字转义进 HTML：尖括号、引号、& 逐字显示，
310	// 不解析成页面元素；实体写法（如 &lt;）转义后显示为 &amp;lt;，仍是普通文字而不会被解码。
311	function escapeHtml(text: string): string {
312	  return text
313	    .replaceAll('&', '&amp;')
314	    .replaceAll('<', '&lt;')
315	    .replaceAll('>', '&gt;')
316	    .replaceAll('"', '&quot;')
317	    .replaceAll("'", '&#39;');
318	}
319	type CompleteIdea = {
320	  id: string;
321	  title: string;
322	  description: string;
323	  scenario: string;
324	  createdAt: string;
325	};
326	function renderIdeaViewPage(idea: CompleteIdea): string {
327	  const scenarioBlock = idea.scenario.trim().length > 0
328	    ? `<p><strong>${VIEW_FIELD_LABELS.scenario}：</strong><span class="pre">${escapeHtml(idea.scenario)}</span></p>\n`
329	    : '';
330	  return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>意见详情 · FeatureHarbor</title><style>
331	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
332	a{color:#175b9c}
333	.pre{white-space:pre-wrap}
334	time{color:#666;font-size:.9rem}
335	.back{display:inline-block;margin-bottom:1.5rem}
336	.idea-id{color:#666;font-size:.9rem;word-break:break-all}
337	</style><main><p><a class="back" href="/">&larr; 返回首页</a></p>
338	<article class="idea">
339	<h2>${escapeHtml(idea.title)}</h2>
340	<p class="pre">${escapeHtml(idea.description)}</p>
341	${scenarioBlock}<p><strong>${VIEW_FIELD_LABELS.createdAt}：</strong><time datetime="${escapeHtml(idea.createdAt)}">${escapeHtml(idea.createdAt)}</time></p>
342	<p class="idea-id">意见标识：${escapeHtml(idea.id)}</p>
343	</article>
344	</main></html>`;
345	}
346	function renderMessagePage(heading: string, message: string): string {
347	  return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${heading} · FeatureHarbor</title><style>
348	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
349	a{color:#175b9c}
350	.back{display:inline-block;margin-bottom:1.5rem}
351	</style><main><p><a class="back" href="/">&larr; 返回首页</a></p>
352	<h2>${heading}</h2>
353	<p>${message}</p>
354	</main></html>`;
355	}
356	// GET /ideas/:id —— 只展示该条已保存意见的独立页面，链接可直接分享、刷新后仍是同一条。
357	// 以记录标识精确匹配（先 decodeURIComponent 还原路径段，中文、空格与特殊字符与原 id 逐字比较），
358	// 标题与说明相同但 id 不同的记录各自打开各自的页面。存储读取失败明确提示加载失败（500），
359	// 不能冒充不存在；能读取但找不到该 id 才提示该意见不存在（404），不展示其他意见。
360	function handleIdeaView(res: ServerResponse, rawPath: string): void {
361	  let targetId: string;
362	  try {
