431	  // 读取失败——不替换、不忽略、不只读取其中的正常片段。
432	  const raw = readFileSync(dataFile);
433	  let text: string;
434	  try {
435	    text = UTF8_DECODER.decode(raw);
436	  } catch {
437	    throw new Error('Invalid UTF-8 in ideas storage');
438	  }
439	  const records: unknown = JSON.parse(text);
440	  if (!Array.isArray(records)) throw new Error('Invalid record list');
441	  // 任意一条记录不完整，整份列表都视为读取失败：
442	  // 不跳过异常记录，也不只返回正常部分。只检查结构，不套用新提交的内容限制：
443	  // 标题首尾空白、正文与场景换行、任意时间字符串都按原样保留，不补字段或改写文字。
