493	  // 超出发生在中途还是末段，都按同一条规则拒绝；即使正文同时不是合法 UTF-8 或合法 JSON，
494	  // 理由也仍是“请求体过大”，不能被后续的 UTF-8/JSON 解析替换成别的错误。
495	  // 恰好达到上限（size === MAX_BODY_BYTES）不在这里拒绝，继续按 JSON 与字段规则判断。
496	  if (tooLarge) {
497	    respond(res, 400, { error: '请求体过大' });
498	    return;
499	  }
500	  // 先按 UTF-8 严格解码整份正文，再解析 JSON：非法字节（单独的续字节、缺少后续
501	  // 字节的多字节字符、不符合 UTF-8 规则的编码）无论在标题、说明、场景还是正文其他
502	  // 位置，都让整次提交失败，不能把坏字节替换成“�”、删字节或只解析正常片段。
503	  // 用户主动输入的“�”本身以合法 UTF-8（EF BF BD）编码，解码结果就是普通文字，照常进入后续判定。
504	  const rawBody = Buffer.concat(chunks);
505	  let bodyText: string;
506	  try {
507	    bodyText = UTF8_DECODER.decode(rawBody);
508	  } catch {
509	    respond(res, 400, { error: '请求体不是有效的 UTF-8' });
510	    return;
511	  }
512	  let payload: unknown;
513	  try {
514	    payload = JSON.parse(bodyText);
515	  } catch {
