// 不带“@”的旧链接仍由服务端兼容，同一标识的新旧链接结果一致。
const viewLink = document.createElement('a');
viewLink.className = 'view-link';
viewLink.href = '/ideas/@' + encodeURIComponent(idea.id);
viewLink.textContent = '查看这条意见';

