  const isViewRoute = route.startsWith(VIEW_PATH_PREFIX) && route.length > VIEW_PATH_PREFIX.length;
  if (!['/', '/health', '/api/ideas'].includes(route) && !isViewRoute) {
    respond(res, 404, { error: 'not found' });
    return;
  }

