    makeIdea({ id: '..', title: '双点标识意见', description: '说明' }),
    makeIdea({ id: specialId, title: '特殊标识意见', description: '说明' }),
    makeIdea({ id: 'r3', title: '', description: '空标题的历史意见' }),
