mkdir -p /tmp/fh-edge && cat > /tmp/fh-edge/ideas.json <<'EOF'
[
  {"id": "@.", "title": "at点", "description": "d1", "scenario": "", "createdAt": "2020-01-01T00:00:00.000Z"},
  {"id": "@..", "title": "at双点", "description": "d2", "scenario": "", "createdAt": "2020-02-02T00:00:00.000Z"},
  {"id": ".foo", "title": "点开头长标识", "description": "d3", "scenario": "", "createdAt": "2020-03-03T00:00:00.000Z"},
  {"id": "a/./b", "title": "路径中段含点", "description": "d4", "scenario": "", "createdAt": "2020-04-04T00:00:00.000Z"}
]
EOF
node server.ts serve --host 127.0.0.1 --port 8901 --data-dir /tmp/fh-edge >/dev/null 2>&1 &
sleep 1
node -e "
for (const id of ['@.', '@..', '.foo', 'a/./b']) {
  const href = '/ideas/@' + encodeURIComponent(id);
  const r = await fetch('http://127.0.0.1:8901' + href);
  const t = await r.text();
  const m = t.match(/意见标识：([^<]*)/);
  console.log(JSON.stringify(id).padEnd(10), '->', href.padEnd(20), r.status, JSON.stringify(m && m[1]));
}
const r = await fetch('http://127.0.0.1:8901/health');
console.log('health:', r.status, JSON.stringify(await r.json()));
"
pkill -f "port 8901"; rm -rf /tmp/fh-edge /tmp/fh-dot-data /tmp/body.html /tmp/b

